e-builder>\n\n	<gutenberg-blocks>\n		<gutenberg-block type=\"core/paragraph\" translate=\"1\">\n			<xpath>//*[self::p or self::h2]</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/heading\" translate=\"1\">\n			<xpath>//*[self::h1 or self::h2 or self::h3 or self::h4 or self::h5 or self::h6]</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/button\" translate=\"1\">\n			<xpath label=\"Button Text\">//a</xpath>\n			<xpath label=\"Button Text\">//button</xpath>\n			<xpath label=\"Button Title\">//a/@title</xpath>\n			<xpath label=\"Button Title\">//button/@title</xpath>\n			<xpath label=\"Button URL\" type=\"link\">//a/@href</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/image\" translate=\"1\">\n			<key type=\"post-ids\" sub-type=\"attachment\" name=\"id\" />\n			<xpath label=\"Caption\">//figure/figcaption</xpath>\n			<xpath label=\"Title\">//figure//img/@title</xpath>\n			<xpath label=\"Alt Text\">//figure//img/@alt</xpath>\n			<xpath label=\"URL\" type=\'link\'>//figure/a/@href</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/gallery\" translate=\"1\">\n			<xpath label=\"Caption\">//figure/figcaption</xpath>\n			<xpath label=\"Alt Text\">//figure/img/@alt</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/media-text\" translate=\"1\">\n			<xpath label=\"Alt Text\">//figure/img/@alt</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/list\" translate=\"1\">\n			<xpath>//ul/li|//ol/li</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/list-item\" translate=\"1\">\n			<xpath>//li</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/quote\" translate=\"1\">\n			<xpath>//blockquote/p</xpath>\n			<xpath>//blockquote/cite</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/audio\" translate=\"1\">\n			<xpath>//figure/figcaption</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/video\" translate=\"1\">\n			<xpath>//figure/figcaption</xpath>\n			<xpath label=\"Track Label\">//video/track/@label</xpath>\n			<key name=\"tracks\">\n				<key name=\"*\">\n					<key name=\"label\" label=\"Track Label\" />\n				</key>\n			</key>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/file\" translate=\"1\">\n			<xpath>//div/a</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/cover\" translate=\"1\">\n			<xpath>//div/p</xpath>\n			<xpath label=\"Alt Text\">//img/@alt</xpath>\n			<key name=\"alt\" label=\"Alt Text\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/search\" translate=\"1\">\n			<key name=\"label\" />\n			<key name=\"placeholder\" />\n			<key name=\"buttonText\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/verse\" translate=\"1\">\n			<xpath>//pre</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/table\" translate=\"1\">\n			<xpath>//th</xpath>\n			<xpath>//td</xpath>\n			<xpath>//figure/figcaption</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/preformatted\" translate=\"1\">\n			<xpath>//pre</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/pullquote\" translate=\"1\">\n			<xpath>//blockquote/p</xpath>\n			<xpath>//blockquote/cite</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/navigation-link\" translate=\"1\">\n			<key name=\"label\" />\n			<key name=\"url\" type=\"link\" />\n			<key name=\"title\" />\n			<key name=\"description\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/navigation-submenu\" translate=\"1\">\n			<key name=\"label\" />\n			<key name=\"url\" type=\"link\" />\n			<key name=\"title\" label=\"Title\" />\n			<key name=\"description\" label=\"Description\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/column\" translate=\"0\" />\n		<gutenberg-block type=\"wpml/language-switcher\" translate=\"0\" />\n		<gutenberg-block type=\"wpml/navigation-language-switcher\" translate=\"0\" />\n		<gutenberg-block type=\"core/columns\" translate=\"0\" />\n		<gutenberg-block type=\"core/group\" translate=\"0\" />\n		<gutenberg-block type=\"core/code\" translate=\"0\" />\n		<gutenberg-block type=\"core/math\" translate=\"0\" />\n		<gutenberg-block type=\"core/more\" translate=\"0\" />\n		<gutenberg-block type=\"core/nextpage\" translate=\"0\" />\n		<gutenberg-block type=\"core/separator\" translate=\"0\" />\n		<gutenberg-block type=\"core/spacer\" translate=\"0\" />\n		<gutenberg-block type=\"core/shortcode\" translate=\"0\" />\n		<gutenberg-block type=\"core/post-excerpt\" translate=\"1\">\n			<xpath>//p/a</xpath>\n			<key name=\"moreText\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/widget-group\" translate=\"1\">\n			<key name=\"title\"></key>\n			<xpath>//h2</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/html\" translate=\"1\">\n			<xpath>/*</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/details\" translate=\"1\">\n			<xpath>//summary</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/social-link\" translate=\"1\">\n			<key name=\"url\" type=\"link\" />\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/query\" translate=\"1\">\n			<key name=\"query\">\n				<key name=\"parents\">\n					<key type=\"post-ids\" name=\"*\" />\n				</key>\n			</key>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/query-pagination-previous\" translate=\"1\">\n			<key name=\"label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/query-pagination-next\" translate=\"1\">\n			<key name=\"label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/read-more\" translate=\"1\">\n			<key name=\"content\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/block\" translate=\"1\">\n			<key name=\"content\">\n				<key name=\"/^.+$/\" search-method=\"regex\">\n					<key name=\"content\"/>\n					<key name=\"text\"/>\n					<key name=\"alt\"/>\n					<key name=\"title\"/>\n					<key name=\"caption\"/>\n					<key name=\"url\" type=\"link\"/>\n					<key name=\"values\">\n						<key name=\"content\"/>\n						<key name=\"text\"/>\n						<key name=\"alt\"/>\n						<key name=\"title\"/>\n						<key name=\"caption\"/>\n						<key name=\"url\" type=\"link\"/>\n					</key>\n				</key>\n			</key>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/page-list\" translate=\"0\">\n			<key name=\"parentPageID\" type=\"post-ids\" sub-type=\"page\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core-embed\" translate=\"1\">\n			<xpath type=\"link\" label=\"Embed URL\">//figure/div</xpath>\n			<xpath label=\"Caption\">//figure/figcaption</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/post-navigation-link\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/categories\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/post-terms\" translate=\"1\">\n			<key name=\"prefix\" label=\"Prefix\" />\n			<key name=\"suffix\" label=\"Suffix\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/post-author\" translate=\"1\">\n			<key name=\"byline\" label=\"Byline\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/home-link\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n			<key name=\"description\" label=\"Description\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/comments-pagination-previous\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/comments-pagination-next\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/playlist\" translate=\"1\">\n			<xpath label=\"Caption\">//figure/figcaption</xpath>\n		</gutenberg-block>\n		<gutenberg-block type=\"core/playlist-track\" translate=\"1\">\n			<key name=\"title\" label=\"Title\" />\n			<key name=\"artist\" label=\"Artist\" />\n			<key name=\"album\" label=\"Album\" />\n			<key name=\"imageAlt\" label=\"Image Alt Text\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/navigation-overlay-close\" translate=\"1\">\n			<key name=\"text\" label=\"Text\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/icon\" translate=\"1\">\n			<key name=\"ariaLabel\" label=\"Aria Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/tabs\" translate=\"1\" />\n		<gutenberg-block type=\"core/tab\" translate=\"1\">\n			<key name=\"label\" label=\"Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/tab-list\" translate=\"1\">\n			<xpath label=\"Tab Title\">//button</xpath>\n			<xpath label=\"Tab List Label\">//div/@aria-label</xpath>\n			<key name=\"ariaLabel\" label=\"Tab List Label\" />\n		</gutenberg-block>\n		<gutenberg-block type=\"core/tab-panel\" translate=\"1\">\n			<key name=\"label\" label=\"Tab Title\" />\n		</gutenberg-block>\n	</gutenberg-blocks>\n</wpml-config>\n\";s:26:\"Advanced Custom Fields PRO\";s:340:\"<wpml-config>\n	<custom-types>\n		<custom-type translate=\"0\">acf-post-type</custom-type>\n		<custom-type translate=\"0\">acf-taxonomy</custom-type>\n		<custom-type translate=\"0\">acf-ui-options-page</custom-type>\n	</custom-types>\n	<custom-fields>\n		<custom-field action=\"copy\">_sections_layout_meta</custom-field>\n	</custom-fields>\n</wpml-config>\n\";}}', 'off'),
(266, 'wpml_global_notices_config', '<wpml-config>\n    <notices>\n        <notice type=\"info\" dismissible=\"1\" id=\"compdev-560-learndash\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-560/ -->\n            <conditions>\n                <plugin>LearnDash LMS</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content><![CDATA[\n<p style=\"margin-top:6px;\">\nRemember to manually connect your LearnDash components after translating them. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-create-multilingual-online-courses-websites-using-learndash-and-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn how to do this</a>.\n</p>\n]]></content>\n        </notice>\n        <notice id=\"compdev-762-wp-residence\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-762/ -->\n            <conditions>\n                <theme>WpResidence</theme>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content><![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate custom fields created with WP Residence, set their translation preferences in <a target=\"_blank\" href=\"/wp-admin/admin.php?page=tm%2Fmenu%2Fsettings&sm=mcsetup#ml-content-setup-sec-cf\">WPML → Settings</a>.\n</p>\n        ]]></content>\n        </notice>\n        <notice id=\"compdev-765-jetengine\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-765/ -->\n            <conditions>\n                <plugin>JetEngine</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate custom post types, custom fields, and taxonomies created with JetEngine, you first need to make them translatable. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-translate-jetengine-with-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn how to do this</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-764-events-manager\" dismissible=\"1\" type=\"warning\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-764/ -->\n            <conditions>\n                <plugin>Events Manager</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n                <screenId>edit-event</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nEvents Manager is no longer compatible with WPML, so you won’t be able to translate your events. <a target=\"_blank\" href=\"https://wpml.org/plugin-functionality/calendar/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Here’s a list of other recommended plugins</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-760-formidable\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-760/ -->\n            <conditions>\n                <plugin>Formidable Forms</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate Formidable Forms with WPML, install the WP Multilingual add-on from Formidable Forms. Then, use the Formidable editor to manually translate your forms. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-translate-formidable-forms-with-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn more</a>\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"comp-4596-oxygen-builder\" dismissible=\"1\" type=\"info\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/comp-4596 -->\n            <conditions>\n                <plugin>Oxygen</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate Oxygen Builder with WPML, install WPML Oxygen Connector, a paid add-on from a third-party developer. <a target=\"_blank\" href=\"https://wpml.org/plugin/oxygen/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn more</a>\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"comp-4596-breakdance\" dismissible=\"1\" type=\"info\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/comp-4596 -->\n            <conditions>\n                <plugin>Breakdance</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate Breakdance with WPML, install WPML Oxygen Connector, a paid add-on from a third-party developer. <a target=\"_blank\" href=\"https://wpml.org/plugin/breakdance/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn more</a>\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice type=\"info\" dismissible=\"1\" id=\"wpmldev-11417\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/wpmldev-11417/ -->\n            <conditions>\n                <plugin>WooCommerce Subscriptions</plugin>\n            </conditions>\n            <locations>\n                <screenId>dashboard</screenId>\n                <screenId>woocommerce_page_wc-orders--shop_subscription</screenId>\n            </locations>\n            <content><![CDATA[\n<h4 style=\"margin-top:0;\">\nWCML 5.7.0 now supports WooCommerce Subscriptions 9.\n</h4>\n<p>\nUpdate WCML to version 5.7.0 or later. After the update, you no longer need to use the legacy subscription editor interface.\n</p>\n]]></content>\n        </notice>\n    </notices>\n</wpml-config>\n', 'off'),
