(191, 30, 'sac_welcome_title', 'Vieta, kur sastapt Dievu un atrast ģimeni.'),
(192, 30, '_sac_welcome_title', 'field_sac_welcome_title'),
(193, 30, 'sac_welcome_text', '<p>Neatkarīgi no tavas pieredzes vai dzīvesstāsta, esi laipni aicināts iepazīt ticību un kopienu kopā ar mums Rīgā.</p>'),
(194, 30, '_sac_welcome_text', 'field_sac_welcome_text'),
(195, 30, 'sac_visit_title', 'Pievienojies mums Rīgā'),
(196, 30, '_sac_visit_title', 'field_sac_visit_title'),
(197, 30, 'sac_visit_text', 'Nāc tāds, kāds esi. Mūsu komanda tevi sagaidīs un palīdzēs iejusties.'),
(198, 30, '_sac_visit_text', 'field_sac_visit_text'),
(199, 30, 'sac_cta_title', 'Šeit ir vieta arī tev.'),
(200, 30, '_sac_cta_title', 'field_sac_cta_title'),
(201, 30, 'sac_cta_text', 'Sper nākamo soli, uzdod jautājumu vai pastāsti, kā varam lūgt kopā ar tevi.'),
